import sys

def fun(a, b, l, r):
    if (r - l + 1) > 2 * (a + b):
        if a <= b:
            return a + 1
        else:
            return 2 * a - b

    flag = [0] * (3 * (a + b) + 1)
    temp = 0
    for i in range(1, a + 1):
        flag[i] = i
        temp = i

    for i in range(a + 1, a + b + 1):
        flag[i] = temp

    for i in range(a + b + 1, a + b + a + 1):
        tc = 1
        while in_range(flag, tc, a + b - a + 1, i - 1):
            tc += 1
        flag[i] = tc
        temp = flag[i]

    for i in range(a + b + a + 1, a + b + a + b + 1):
        flag[i] = temp

    for i in range(2 * (a + b) + 1, 3 * (a + b) + 1):
        flag[i] = flag[i - (a + b)]

    flagc = [0] * 25
    templ = l % (a + b)
    if templ == 0:
        templ += a + b
    tempr = r - l + templ
    if tempr < templ:
        tempr += a + b
    for i in range(templ, tempr + 1):
        flagc[flag[i]] = 1

    res = sum(flagc[1:25])
    return res

def in_range(a, b, l, r):
    for i in range(l, r + 1):
        if a[i] == b:
            return True
    return False

def main():
    input_data = sys.stdin.read().strip().split()
    a, b, l, r = map(int, input_data)
    print(fun(a, b, l, r))

if __name__ == "__main__":
    main()

